//! Generic webhook ingress for tools.//!//! Exposes `/webhook/tools/{tool}` so external webhook providers can POST//! payloads that are normalized by the target tool into `system_event`s.use std::collections::HashMap;use std::sync::Arc;use axum::{    Json, Router,    extract::{DefaultBodyLimit, Path, Query, State},    http::{HeaderMap, Method, StatusCode},    routing::{get, post},};use serde::{Deserialize, Serialize};use subtle::ConstantTimeEq;use crate::agent::routine_engine::RoutineEngine;use crate::context::JobContext;use crate::secrets::SecretsStore;use crate::tools::ToolRegistry;/// Shared routine engine slot, populated by Agent after startup.pub type RoutineEngineSlot = Arc<tokio::sync::RwLock<Option<Arc<RoutineEngine>>>>;/// Shared state for the generic tools webhook ingress.#[derive(Clone)]pub struct ToolWebhookState {    pub tools: Arc<ToolRegistry>,    pub routine_engine: RoutineEngineSlot,    pub user_id: String,    pub secrets_store: Option<Arc<dyn SecretsStore + Send + Sync>>,}#[derive(Debug, Serialize)]struct ToolWebhookResponse {    status: &'static str,    tool: String,    emitted_events: usize,    fired_routines: usize,}#[derive(Debug, Deserialize)]struct ToolWebhookOutput {    #[serde(default)]    emit_events: Vec<SystemEventIntent>,}#[derive(Debug, Deserialize)]struct SystemEventIntent {    source: String,    event_type: String,    #[serde(default)]    payload: serde_json::Value,}const MAX_WEBHOOK_BODY_BYTES: usize = 64 * 1024;/// Build routes for tool-driven webhook ingestion.pub fn routes(state: ToolWebhookState) -> Router {    Router::new()        .route("/webhook/tools/{tool}", post(tool_webhook_handler))        .route(            "/webhook/tools/{tool}/{*rest}",            post(tool_webhook_with_rest_handler),        )        .route("/webhook/tools/{tool}", get(tool_webhook_health))        .layer(DefaultBodyLimit::max(MAX_WEBHOOK_BODY_BYTES))        .with_state(state)}